// Schema-2 golden decoder test (W7). Standalone: run alongside the
// existing profile_wire_test.cc. Fixture bytes come from native/golden_v2.inc,
// generated by tests/golden_v2/gen_golden_v2.py from an explicit fake field
// dictionary -- NOT patched from the v1 golden fixture.
//
// This test asserts the W3-layout schema 2: the u8
// webrtc_ip_handling_policy byte sits AFTER timezone and BEFORE slot_count
// (docs/webrtc-schema2-native.md). Independent Python/Rust encoders verify
// the fixture; this suite exercises decoding, boundaries and v1 compatibility.
#include "profile_wire.h"

#include <array>
#include <cstdlib>
#include <iostream>
#include <vector>

#include "golden.inc"
#include "golden_v2.inc"

using Bytes = std::vector<std::uint8_t>;
int checks = 0;

void Check(bool ok, const char* what) {
  ++checks;
  if (!ok) {
    std::cerr << "FAIL check " << checks << ": " << what << '\n';
    std::exit(1);
  }
}

void Bad(const Bytes& bytes, const char* what) {
  ++checks;
  if (lengsuo::DecodeProfile(bytes)) {
    std::cerr << "FAIL check " << checks << ": accepted " << what << '\n';
    std::exit(1);
  }
}

// Frozen v2 prefix boundary: bytes [0, 65) are the schema-1-compatible
// framing through the end of timezone; byte 65 is the policy byte; bytes
// [66, 148) are the unchanged slot table (slot_count u16 at 66-67).
// Verified against the dictionary walk: 5 magic + 4 + 4 + (2+5) + (2+2)
// + 8 + 1 + 4 + 4 + 1 + 4 + 2 + 4 + 1 + (2+5) + (2+3) = 65.
constexpr std::size_t kTzEnd = 65;
constexpr std::size_t kPolicyOffset = kTzEnd;
constexpr std::size_t kSlotTableOffset = kTzEnd + 1;

// Rebuild a schema-2 stream from the frozen golden with a given policy byte
// substituted in the designated slot (a single-field dictionary change,
// re-emitted, not a splice of another fixture).
Bytes V2WithPolicy(std::uint8_t policy) {
  Bytes bytes(std::begin(kGoldenV2), std::end(kGoldenV2));
  bytes[kPolicyOffset] = policy;
  return bytes;
}

// Dictionary case: same field values, schema_version := 1, policy section
// omitted entirely (the encoder's version branch drops it).
Bytes AsV1(const Bytes& v2) {
  Bytes bytes = v2;
  bytes[8] = 1;  // schema_version u32, last byte (big-endian, value 1..2)
  bytes.erase(bytes.begin() + static_cast<std::ptrdiff_t>(kPolicyOffset));
  return bytes;
}

void ExpectFields(const lengsuo::ParsedProfile& p, std::uint8_t policy,
                  const char* what) {
  Check(p.schema_version == 2, what);
  Check(p.noise_version == 1, what);
  Check(p.environment_id == "env-1", what);
  Check(p.pool_version == "p1", what);
  Check(p.noise_seed == std::array<std::uint8_t, 8>{0, 1, 2, 3, 4, 5, 6, 7},
        what);
  Check(p.platform == lengsuo::Platform::Windows, what);
  Check(p.width == 1920 && p.height == 1080 && p.color_depth == 24, what);
  Check(p.dpr_milli == 1000 && p.cpu_cores == 8 && p.memory_mib == 8192 &&
            p.max_touch_points == 0,
        what);
  Check(p.language == "en-US" && p.timezone == "UTC", what);
  Check(p.slots == std::array<std::uint32_t, 7>{3, 1, 5, 4, 6, 7, 2}, what);
  Check(p.webrtc_policy.has_value() && *p.webrtc_policy == policy, what);
}

int main() {
  const Bytes v2(std::begin(kGoldenV2), std::end(kGoldenV2));
  Check(v2.size() == 148, "golden v2 is 148 bytes");
  // The frozen golden's policy byte matches the dictionary value (2).
  Check(v2[kPolicyOffset] == 2, "golden v2 policy byte at offset 65");
  // v1 golden bytes are unchanged by schema 2 and remain 147 bytes.
  const Bytes v1(std::begin(kGolden), std::end(kGolden));
  Check(v1.size() == 147, "v1 golden still 147 bytes");
  Check(v1 == AsV1(v2), "v1 stream = v2 minus the policy section");

  // --- Positive: all four policy values decode with full field parity. ---
  for (const std::uint8_t policy : {std::uint8_t{0}, std::uint8_t{1},
                                    std::uint8_t{2}, std::uint8_t{3}}) {
    auto p = lengsuo::DecodeProfile(V2WithPolicy(policy));
    Check(p.has_value(), "v2 policy 0..3 accepted");
    ExpectFields(*p, policy, "v2 decoded fields");
  }

  // --- Schema 1 carries no policy statement. ---
  {
    auto p = lengsuo::DecodeProfile(v1);
    Check(p.has_value(), "v1 golden decodes");
    Check(p->schema_version == 1 && !p->webrtc_policy.has_value(),
          "v1 has no webrtc statement");
  }

  // --- Invalid policy values in the v2 slot. ---
  for (const int policy : {4, 5, 128, 255}) {
    Bad(V2WithPolicy(static_cast<std::uint8_t>(policy)), "out-of-range policy");
  }

  // --- Missing policy byte (truncated v2). ---
  {
    Bytes truncated;
    truncated.insert(truncated.end(), v2.begin(), v2.begin() + kPolicyOffset);
    truncated.insert(truncated.end(), v2.begin() + kSlotTableOffset, v2.end());
    Bad(truncated, "v2 without policy byte");
  }
  // Slice-truncation of any v2 stream (prefix of a valid stream fails).
  {
    const Bytes good = V2WithPolicy(1);
    for (std::size_t n = 0; n < good.size(); ++n) {
      Bad(Bytes(good.begin(), good.begin() +
                static_cast<Bytes::difference_type>(n)),
          "truncated v2 prefix");
    }
  }

  // --- Extra bytes: duplicated policy slot and trailing byte. ---
  {
    Bytes dup = v2;
    dup.insert(dup.begin() + static_cast<std::ptrdiff_t>(kSlotTableOffset),
               v2[kPolicyOffset]);
    Bad(dup, "duplicated policy byte");
  }
  {
    Bytes trailing = v2;
    trailing.push_back(0);
    Bad(trailing, "trailing byte after slot table");
    trailing = V2WithPolicy(3);
    trailing.push_back(2);
    Bad(trailing, "trailing byte (policy 3)");
  }

  // --- Unknown schema versions inside the v2 frame. ---
  for (const std::uint32_t version : {0u, 3u, 4u, 0xffffffffu}) {
    Bytes bytes = v2;
    for (std::size_t i = 0; i < 4; ++i) {
      bytes[8 - i] = static_cast<std::uint8_t>((version >> (8 * i)) & 255u);
    }
    Bad(bytes, "unknown schema version in v2 frame");
    Bytes as_v1 = AsV1(v2);  // 147-byte framing must not smuggle bad versions
    for (std::size_t i = 0; i < 4; ++i) {
      as_v1[8 - i] = static_cast<std::uint8_t>((version >> (8 * i)) & 255u);
    }
    Bad(as_v1, "unknown schema version in v1 frame");
  }

  std::cout << "PASS " << checks << " assertions\n";
}
